def _text_language(text: str) -> str | None:
    """es or en when the words of a text say so clearly; None for a name or a mix."""

    spanish, english = read_request(text).evidence
    if spanish >= 2 and spanish > english:
        return "es"
    if english >= 2 and english > spanish:
        return "en"
    return None


# The words of a number up to twelve: a page that writes «tres naciones» states
# the 3 a report may write in digits, and the other way round.
_SMALL_NUMBER_WORDS = {
    "0": ("cero", "zero"), "1": ("uno", "una", "one"), "2": ("dos", "two"),
    "3": ("tres", "three"), "4": ("cuatro", "four"), "5": ("cinco", "five"),
    "6": ("seis", "six"), "7": ("siete", "seven"), "8": ("ocho", "eight"),
    "9": ("nueve", "nine"), "10": ("diez", "ten"), "11": ("once", "eleven"),
    "12": ("doce", "twelve"),
}


def _search_report_unsourced_numbers(sentence: str, grounds: str) -> list[str]:
    """The numbers of a report sentence that neither the pages it cites nor the request write."""

    folded_grounds = _reading_fold(grounds)
    missing: list[str] = []
    # A number glued to letters is part of a name («24timezones.com», «PM2.5»).
    for number in re.findall(r"(?<![\w.,:+-])\d+(?:[.,:]\d+)*(?!\w)", sentence):
        forms = {number, number.replace(",", "."), number.replace(".", ","), re.sub(r"[.,]", "", number)}
        if any(
            re.search(r"(?<![\d.,])" + re.escape(form) + r"(?![\d]|[.,]\d)", folded_grounds)
            for form in forms
        ) or any(
            re.search(r"\b" + word + r"\b", folded_grounds)
            for word in _SMALL_NUMBER_WORDS.get(number.lstrip("0") or "0", ())
        ):
            continue
        missing.append(number)
    return missing


def _search_report_unsourced_words(text: str, payload: dict, user_text: str) -> list[str]:
    """The words of the report that no result and no request shares.

    Judged sentence by sentence, the same for a named page as for an unnamed
    one (WEB1889: naming the page vouched for «problemas de conexion», which no
    result carried). The SEARCH2019 hint names these words back to the model.

    Uso real tanda 4 «Whats the air quality hoy?»: the pages were English and
    the report Spanish, so every translated word («calidad», «pronóstico»,
    «contaminantes») was «unsourced», the three drafts fell and the turn ended
    in the bare list of titles. A sentence that cites only pages written in the
    other language cannot be checked word by word; its numbers still must be
    the pages' own. And one paraphrased word («abarcan», «explanation»,
    «opción») among many that the pages do write is the report's wording, not a
    claim: a claim brings words of its own, and every number of a sentence is
    checked whatever its words.
    """

    results_text = _search_results_text(payload)
    if results_text is None:
        return []
    seen = payload.get("seen")
    # Tanda 4c: the city this PC's search was made near, and saying it was near, are observed too.
    near = seen.get("near") if isinstance(seen, dict) and isinstance(seen.get("near"), str) else ""
    near_voice = f"{near} cerca near" if near.strip() else ""
    observed = set(re.findall(r"[a-z]+", _reading_fold(results_text))) | set(
        re.findall(r"[a-z]+", _reading_fold(f"{user_text} {near_voice}"))
    )
    results = [item for item in _search_results_of(payload) if isinstance(item, dict)]

    def page_text(items: list[dict]) -> str:
        return "\n".join(str(item.get(key) or "") for item in items for key in ("title", "snippet"))

    words: list[str] = []
    for sentence in re.split(r"(?<=[.!?])\s+", str(text).strip()):
        numbers = _search_report_unsourced_numbers(sentence, page_text(results) + "\n" + (user_text or ""))
        content = 0
        lettered: list[str] = []
        for word in re.findall(r"[a-z]+", _reading_fold(sentence)):
            if (
                len(word) < 5
                or word in _SEARCH_REPORT_GRAMMAR_WORDS
                # The report's own voice, conjugated: «incluyendo», «explicando».
                or any(
                    word.startswith(own) and len(word) - len(own) <= 4
                    for own in _SEARCH_REPORT_OWN_WORDS
                    if len(own) >= 5
                )
            ):
                continue
            content += 1
            # Inflection is tolerated by the first four letters («enviar» for
            # «envío»), and a short observed word may take its plural
            # («yenes» for «yen»); a word no result shares that much is the
            # model's.
            if word in lettered or any(
                seen_word.startswith(word[:4])
                or (len(seen_word) >= 3 and word.startswith(seen_word) and len(word) - len(seen_word) <= 2)
                for seen_word in observed
            ):
                continue
            lettered.append(word)
        language = _text_language(sentence)
        translated = (
            language is not None
            # A translation says what the page says; a bare verdict («está
            # prohibido») is no translation of a page and is judged by its words.
            and content >= 4
            and all(_text_language(page_text([item])) not in (None, language) for item in results)
        )
        if translated or (len(lettered) == 1 and content >= 8):
            lettered = []
        words.extend(word for word in numbers + lettered if word not in words)
    return words


def _search_report_unsourced_claim(text: str, payload: dict, user_text: str) -> bool:
    """A sentence of the report states something that is neither in a result nor asked."""

    if (
        _entity_lookup_query(user_text or "") is not None
        # WEB1889: la pregunta de investigacion SI es un informe, y esta
        # exencion era lo que dejaba pasar un final sin una sola pagina
        # nombrada. Quien-o-que-es y la curiosidad siguen fuera: esas
        # contestan con el fragmento, no informan de paginas.
        or curiosity_request(user_text or "")
    ):
        return False
    return bool(_search_report_unsourced_words(text, payload, user_text))


# Uso real 2026-09-23 «cuál es la tasa de cambio entre el peso chileno y el yen»:
# «Nuestro conversor de moneda le permite conocer el cambio…» pasted a snippet
# and made the page's «we» BAXY's own; «le decimos en cuánto está el dólar»
# the same. BAXY reports pages in its own voice; a quoted title may keep theirs.
# A bare «we» stays out: «AI as we know it today» is the generic we, not a page.
_PAGE_FIRST_PERSON_PLURAL = re.compile(
    r"\b(?:nuestr[oa]s?|nosotr[oa]s|hemos|(?:le|les|te|os)\s+[a-z]+mos|our|ours)\b"
)


def _search_report_speaks_as_a_page(text: str, payload: dict, user_text: str) -> bool:
    """The report of a verified search speaks in the first person plural of a page."""

    if _search_results_text(payload) is None:
        return False
    unquoted = _reading_fold(re.sub(r"[«\"“][^»\"”]{1,400}[»\"”]", " ", str(text)))
    asked = _reading_fold(user_text or "")
    return any(
        re.search(r"\b" + re.escape(found[0]) + r"\b", asked) is None
        for found in _PAGE_FIRST_PERSON_PLURAL.finditer(unquoted)
    )


# Owner rule 2026-09-24: a web lookup is invisible. «¿Qué son las Tortugas
# Ninja?» is answered «Las Tortugas Ninja son cuatro tortugas mutantes…»,
# never «Según ejemplo.com…», «Busqué en internet y encontré…» or a list of
# pages: the person must not notice that BAXY looked it up. What the answer
# says is still only what the pages say (_search_report_unsourced_words).
_SEARCH_ATTRIBUTION = re.compile(
    r"\b(?:segun|according\s+to|de\s+acuerdo\s+con|citing|cita\s+a)\s+(?:(?:el|la|los|las|un|una|the|an?)\s+)?"
    r"(?:[\w-]+\.(?:com|org|net|es|cl|mx|ar|co|info|gov|edu|io|uk|de|fr|cat|pe|us)\b|"
    r"(?:pagina|paginas|sitio|sitios|web|articulo|articulos|fuente|fuentes|wikipedia|page|pages|site|sites|"
    r"website|article|articles|source|sources|result|results|resultado|resultados)\b)"
)
_SEARCH_MECHANICS = re.compile(
    r"\b(?:busque|he\s+buscado|estuve\s+buscando|hice\s+una\s+busqueda|la\s+busqueda|mi\s+busqueda|"
    r"(?:encontre|halle|vi)\s+(?:estas|esta|varias|algunas|unas|tres|dos|cinco)\s+(?:paginas?|resultados?|fuentes?|sitios?)|"
    r"(?:estas|esas|las|varias|algunas)\s+(?:paginas|fuentes|sitios\s+web)|"
    r"(?:en|de)\s+(?:ese|este|un|otro)\s+sitio|(?:en|de)\s+(?:esa|esta|una|otra)\s+pagina|"
    r"ninguna\s+de\s+(?:estas|las)\s+paginas|resultados\s+de\s+(?:la\s+)?busqueda|"
    r"i\s+searched|i\s+looked\s+(?:it\s+)?up|my\s+search|the\s+search|search\s+results?|"
    r"i\s+found\s+(?:these|this|some|several|a\s+few|three|two|five)\s+(?:pages?|results?|sources?|sites?)|"
    r"(?:these|those|the|several|some)\s+(?:pages|sources|websites)|(?:on|from)\s+(?:that|this|one|another)\s+(?:site|page)|"
    r"none\s+of\s+(?:these|the)\s+pages)\b"
)
# «según Tripadvisor», «according to BBC Mundo»: a source named by its proper name.
_SEARCH_NAMED_SOURCE = re.compile(
    r"\b(?:[Ss]eg[uú]n|[Aa]ccording\s+to|[Dd]e\s+acuerdo\s+con)\s+(?:(?:el|la|los|las|the)\s+)?[A-ZÁÉÍÓÚÑ][\w.-]*"
)


def _search_report_shows_the_search(text: str, payload: dict, user_text: str) -> bool:
    """The answer to a verified search tells the search: a source cited, a result's site named, or how it was
    found. The person's own words and a snippet's own words are not the search showing."""

    results_text = _search_results_text(payload)
    if results_text is None:
        return False
    folded = _reading_fold(re.sub(r"[«\"“][^»\"”]{1,400}[»\"”]", " ", str(text)))
    grounds = _reading_fold(f"{user_text or ''}\n" + "\n".join(
        str(item.get(key) or "") for item in _search_results_of(payload) if isinstance(item, dict)
        for key in ("title", "snippet")
    ))
    named_source = (
        _reading_fold(found.group(0))
        for found in _SEARCH_NAMED_SOURCE.finditer(re.sub(r"[«\"“][^»\"”]{1,400}[»\"”]", " ", str(text)))
    )
    for found in (
        *(match.group(0) for match in _SEARCH_ATTRIBUTION.finditer(folded)),
        *(match.group(0) for match in _SEARCH_MECHANICS.finditer(folded)),
        *named_source,
    ):
        # A snippet that itself says «según la OMS» may be repeated with its words.
        if found not in grounds:
            return True
    for host in _search_result_hosts(payload, limit=len(_search_results_of(payload))):
        if host in folded:
            return True
        for label in host.split("."):
            # «tripadvisor»: a site said by its name. A label the person or the pages use as a word
            # («valparaiso» of valparaiso.cl in a snippet about Valparaíso) is that word, not the site.
            word = r"\b" + re.escape(label) + r"\b"
            if (
                len(label) >= 5
                and re.search(word, folded) is not None
                and re.search(word, grounds) is None
            ):
                return True
    return False


# Owner rule 2026-09-24: a web answer is short, like Jarvis: one or two sentences.


def _search_report_runs_long(text: str, payload: dict, user_text: str) -> bool:
    """The answer to a verified search runs past two sentences."""

    if _search_results_text(payload) is None:
        return False
    sentences = [part for part in re.split(r"(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÑ¿¡«\"])", str(text).strip()) if part.strip()]
    return len(sentences) > 2


def _verified_search_results(situation: dict) -> bool:
    """A completed, verified web.search whose observation carries results."""

    if (
        situation.get("kind") != "operation"
        or situation.get("operation") != "web.search"
        or situation.get("verified") is not True
        or situation.get("succeeded") is not True
    ):
        return False
    results = _merged_observed(situation).get("results")
    return isinstance(results, list) and bool(results)


def _search_unsupported_claim(text: str, results_text: str) -> str | None:
    """A weather assertion in a search report that no result states verbatim."""

    folded_results = _reading_fold(results_text)
    for match in _SEARCH_WEATHER_CLAIM.finditer(_reading_fold(text)):
        claim = re.sub(r"\s+", " ", match.group(0)).strip()
        if claim and claim not in folded_results:
            return claim
    return None


_MEANS_WORDS = (
    r"(?:python|powershell|bash|cmd|scripts?|c[oó]digo|code|terminal|consola|console|api)"
)
# «sin Python», «sin usar un script», «no usé la terminal», «without running code»:
# a negated mention is the honest disclaimer, not a claim.
_NEGATED_MEANS = re.compile(
    r"\b(?:sin(?:\s+(?:usar|ejecutar|correr|necesitar|recurrir\s+a|tener\s+que\s+usar))?|"
    r"no\s+(?:us[eé]|utilic[eé]|ejecut[eé]|corr[ií]|necesit[oé]|recurr[ií]\s+a|hace\s+falta|"
    r"necesito|uso|utilizo|ejecuto)|"
    r"without(?:\s+(?:using|running|needing))?|"
    r"(?:did\s+not|didn't|don't|do\s+not)\s+(?:use|run|need)|no\s+need\s+(?:for|of))"
    r"(?:\s+(?:el|la|un|una|ningun|ninguna|a|the|any))?\s+" + _MEANS_WORDS + r"\b",
    re.IGNORECASE,
)


def _claims_declined_means(text: str) -> bool:
    """True when the reply mentions the declined means other than to deny it."""

    folded = _NEGATED_MEANS.sub(" ", _reading_fold(text))
    return re.search(r"\b" + _MEANS_WORDS + r"\b", folded) is not None


# NETWORK1729: a network name the reply quotes, in guillemets, curly or straight quotes.
_QUOTED_NAME = re.compile("[" + chr(171) + chr(8220) + chr(34) + "]([^" + chr(187) + chr(8221) + chr(34) + "]{1,64})[" + chr(187) + chr(8221) + chr(34) + "]")


def _weather_number_forms(value: object) -> set[str]:
    """The ways a person writes an observed weather number: 18.8, 18,8, 19, 18."""

    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return set()
    forms = {str(value), str(value).replace(".", ",")}
    if float(value).is_integer():
        forms.add(str(int(value)))
    else:
        forms.add(str(round(value)))
        forms.add(str(int(value)))
    return forms


def _states_weather_number(text: str, value: object) -> bool:
    """The reply states this observed number on its own, not inside another («8» in «18»)."""

    return any(
        re.search(r"(?<![\d.,])" + re.escape(form) + r"(?![\d]|[.,]\d)", text) is not None
        for form in _weather_number_forms(value)
    )


# A rain amount as a reply writes it (folded): «0 mm», «2,5 milimetros», «1 pulgada».
_RAIN_AMOUNT = re.compile(
    r"(?<![\w.,])(\d+(?:[.,]\d+)?)\s*(mm|milimetros?|millimet(?:er|re)s?|pulgadas?|inch(?:es)?|"
    r"cm|centimetros?|centimet(?:er|re)s?|litros?|lit(?:er|re)s?)\b"
)


# What makes a number a weather measurement in a reply: its unit right after it.
_WEATHER_MEASURE_UNIT = re.compile(
    r"\s*(?:°|º|%|grados?\b|degrees?\b|por\s*ciento\b|percent\b|km|mm|mil[ií]metros?\b|millimet|"
    r"pulgadas?\b|inch|cm\b|mph\b|m/s\b)",
    re.IGNORECASE,
)


def _weather_clock_forms(value: object) -> set[str]:
    """The numbers of an observed sun clock «07:05» as a reply writes them: 07, 7, 05, 5."""

    if not isinstance(value, str) or re.fullmatch(r"\d\d:\d\d", value) is None:
        return set()
    hour, minute = value.split(":")
    return {hour, str(int(hour)), minute, str(int(minute))}


def _weather_asks_rain(user_text: str) -> bool:
    """The weather question asks about rain, rain gear or an amount of it
    («¿lloverá?», «¿me llevo el paraguas?», «how many inches»)."""

    return re.search(
        r"\b(?:llov\w*|lluvi\w*|llueve|rain\w*|paraguas|umbrella|chubasquero|impermeable|"
        r"pulgadas|inches|milimetros|millimeters)\b",
        _reading_fold(user_text),
    ) is not None


def _weather_asks_tomorrow(user_text: str) -> bool:
    """The weather question is about tomorrow or a later day."""

    return weather_asks_later_day(user_text) or re.search(
        r"(?<!esta )\b(?:manana|tomorrow)\b", _reading_fold(user_text)
    ) is not None


_WEATHER_MEASURE_FIELDS = {
    "humidity": ("humidityPercent", "the humidity", "la humedad"),
    "wind": ("windKmh", "the wind", "el viento"),
    "apparent": ("apparentC", "the feels-like temperature", "la sensación térmica"),
}


def _weather_answer_instruction(user_text: str, language: str) -> str:
    """What a weather reply says: the one thing the question asks of the read.

    Owner 2026-09-24 («conciso… que te responda de una»): the old instruction
    always asked for the temperature and the sky and then added the asked
    thing, so «¿Cuál es la tasa de humedad de hoy?» got three facts and «my
    current location» got the weather too. Only the asked focus is sent now;
    the other readings stay in seen and are not mentioned.
    """

    english = language == "en"
    fields = (
        "seen is the weather of seen.location (seen.country) now: temperatureC, apparentC (feels like), "
        "condition (sky), windKmh, humidityPercent, today.maxC/minC and today.rainProbabilityPercent, "
        "tomorrow.maxC/minC, tomorrow.rainProbabilityPercent and tomorrow.condition; today/tomorrow "
        "sunrise and sunset are local sun times; seen.airQuality is the air now (usAqi with its category, "
        "pm25 and pm10 in µg/m³). "
        if english
        else "seen es el clima de seen.location (seen.country) ahora: temperatureC, apparentC (sensación "
        "térmica), condition (cielo), windKmh, humidityPercent, today.maxC/minC y "
        "today.rainProbabilityPercent, tomorrow.maxC/minC, tomorrow.rainProbabilityPercent y "
        "tomorrow.condition; sunrise y sunset de today/tomorrow son las horas locales del sol; "
        "seen.airQuality es el aire ahora (usAqi con su category, pm25 y pm10 en µg/m³). "
    )
    measures = weather_asked_measures(user_text) - {"temperature"}
    if asks_own_place(user_text):
        focus = (
            "The person asked where they are: say seen.location with seen.region and seen.country as "
            "the approximate place of this PC, and nothing about the weather."
            if english
            else "La persona preguntó dónde está: di seen.location con seen.region y seen.country como "
            "el lugar aproximado de este PC, y nada del clima."
        )
    elif weather_asks_air(user_text):
        focus = (
            "The person asked about the air: give the index, its category and PM2.5; if "
            "seen.airQuality is null, say the air quality could not be read."
            if english
            else "La persona preguntó por el aire: da el índice, su categoría y el PM2.5; si "
            "seen.airQuality es null, di que no se pudo leer la calidad del aire."
        )
    elif weather_asks_sun_time(user_text):
        focus = (
            "The person asked when the sun rises or sets: give that time for the day asked "
            "(tomorrow's for tomorrow or a later day)."
            if english
            else "La persona preguntó a qué hora sale o se pone el sol: da esa hora del día preguntado "
            "(la de mañana para mañana o un día posterior)."
        )
    elif _weather_asks_rain(user_text):
        focus = (
            "The person asked about rain (or rain gear, or an amount of rain): answer with the rain "
            "probability of the day asked, tomorrow's for tomorrow or a later day."
            if english
            else "La persona preguntó por la lluvia (o por algo para la lluvia, o una cantidad): contesta "
            "con la probabilidad de lluvia del día preguntado, la de mañana para mañana o un día posterior."
        )
    elif _weather_asks_tomorrow(user_text):
        focus = (
            "The person asked about tomorrow or a later day: give tomorrow's sky, maximum and minimum and "
            "rain probability."
            if english
            else "La persona preguntó por mañana o un día posterior: da el cielo, la máxima, la mínima y la "
            "probabilidad de lluvia de mañana."
        )
    elif measures:
        asked = [
            _WEATHER_MEASURE_FIELDS[name][1 if english else 2] + f" ({_WEATHER_MEASURE_FIELDS[name][0]})"
            for name in ("humidity", "wind", "apparent")
            if name in measures
        ]
        focus = (
            "The person asked about " + " and ".join(asked) + ": give that value."
            if english
            else "La persona preguntó por " + " y ".join(asked) + ": da ese valor."
        )
    elif "temperature" in weather_asked_measures(user_text):
        focus = (
            "The person asked about the temperature: give the current temperature of seen.location, naming it."
            if english
            else "La persona preguntó por la temperatura: da la temperatura actual de seen.location, nombrándolo."
        )
    else:
        focus = (
            "Say the current temperature and sky of seen.location, naming it; if the person asked what to "
            "wear or carry, answer that from the temperature."
            if english
            else "Di la temperatura actual y el cielo de seen.location, nombrándolo; si la persona preguntó "
            "qué ponerse o llevar, contéstalo desde la temperatura."
        )
    closing = (
        " Answer only that, in one short sentence (two at most), with the observed numbers and their units "
        "(°C, km/h, %); no other readings. The read covers today and tomorrow only: for a later day, say so. "
        "Say it directly, without naming where it was read. Nothing was opened or changed."
        if english
        else " Contesta sólo eso, en una oración corta (dos como máximo), con los números observados y sus "
        "unidades (°C, km/h, %); sin otras lecturas. La lectura cubre sólo hoy y mañana: para un día "
        "posterior, dilo. Dilo directamente, sin nombrar de dónde se leyó. No se abrió ni se cambió nada."
    )
    return fields + focus + closing


def _weather_fact_defect(text: str, payload: dict, user_text: str) -> str:
    """REOPEN1993 grupo W: every number in a weather reply is an observed one
    (temperatures, wind, humidity, rain probability) and the place is named;
    a question about tomorrow or rain is answered with tomorrow's probability."""

    if payload.get("operation") != "weather.current":
        return ""
    seen = payload.get("seen")
    if not isinstance(seen, dict) or "temperatureC" not in seen:
        return ""
    observed: set[str] = set()
    for key in ("temperatureC", "apparentC", "humidityPercent", "windKmh", "precipitationMm"):
        observed |= _weather_number_forms(seen.get(key))
    for day in ("today", "tomorrow"):
        block = seen.get(day)
        if isinstance(block, dict):
            for key in ("maxC", "minC", "rainProbabilityPercent"):
                observed |= _weather_number_forms(block.get(key))
            for key in ("sunrise", "sunset"):
                observed |= _weather_clock_forms(block.get(key))
    air = seen.get("airQuality")
    if isinstance(air, dict):
        # Tanda 4c «Whats the air quality hoy?»: the index and the particles of the same read.
        for key in ("usAqi", "pm25", "pm10"):
            observed |= _weather_number_forms(air.get(key))
        # «PM2.5», «PM10» name what is measured; their digits are not a measurement.
        text = re.sub(r"(?i)\bpm\s*(?:2[.,]5|10)\b", "PM", text)
    # Tanda 4 «Digame el weather lunes 13 en North Carolina»: every draft that said which day could not be read
    # («no tengo el pronóstico del lunes 13») died here and the turn ended in no_response. A number the person
    # said is theirs to repeat, but never as a measurement: «13 °C» must still be observed.
    asked_numbers = set(re.findall(r"(?<![\w.,])\d+(?:[.,]\d+)?(?![\w]|[.,]\d)", user_text or ""))
    # A number that ends the sentence («a las 20:15.») is still a number said.
    for found in re.finditer(r"(?<![\w.,])-?\d+(?:[.,]\d+)?(?!\w|[.,]\d)", text):
        number = found.group()
        if number in observed or number.lstrip("-") in observed:
            continue
        if number in asked_numbers and re.match(_WEATHER_MEASURE_UNIT, text[found.end():]) is None:
            continue
        return "invented_number"
    folded_text = _reading_fold(text)
    # An amount of rain is only the observed precipitation, in its millimetres
    # (none is none in any unit): an observed temperature or percentage said
    # as «14 pulgadas» is an invented amount even though the number was read.
    rain_mm = seen.get("precipitationMm")
    for amount, unit in _RAIN_AMOUNT.findall(folded_text):
        value = float(amount.replace(",", "."))
        if not (
            (value == 0 and rain_mm == 0)
            or (unit.startswith(("mm", "mil")) and amount in _weather_number_forms(rain_mm))
        ):
            return "invented_number"
    asks = _reading_fold(user_text or "")
    tomorrow = seen.get("tomorrow")
    asks_tomorrow = _weather_asks_tomorrow(user_text or "")
    sun_time = weather_asks_sun_time(user_text or "")
    rain_asked = _weather_asks_rain(user_text or "")
    location = seen.get("location")
    # Owner 2026-09-24 (concise, «de una»): a measure asked by its name is the
    # answer; the temperature and the sky are not demanded next to it.
    narrow_measures = weather_asked_measures(user_text or "") - {"temperature"}
    # Uso real tanda 2 «¿Cuántas pulgadas are we getting today?»: a narrow
    # question about here (rain, the sun, the air, one measure) is answered by
    # its value; the place must be named when the person named one, or for a
    # general report.
    asked_place = _reading_fold(_weather_location(user_text or "") or "")
    narrow = rain_asked or sun_time or bool(narrow_measures) or weather_asks_air(user_text or "")
    if isinstance(location, str) and location and (asked_place or not narrow):
        # WEATHER2031 «how's the weather in Santiago»: the geocoder says «Santiago
        # de Chile»; the head of that name (before « de …» or a comma) names the
        # place as well as the whole.
        folded_location = _reading_fold(location)
        head = re.split(r"\s+de\s+|,", folded_location, maxsplit=1)[0].strip()
        # Uso real 2026-09-23 «what's the weather like in london»: the geocoder
        # names the place in Spanish («Londres»); the English reply names it as
        # the person did, and that is the same place named.
        if (
            folded_location not in folded_text
            and not (len(head) >= 3 and head in folded_text)
            and not (len(asked_place) >= 3 and re.search(r"\b" + re.escape(asked_place) + r"\b", folded_text))
        ):
            return "missing_state"
    if asks_own_place(user_text or ""):
        # Tanda 4c «i'd like to know my current location»: the place read is the
        # answer (named above); the weather was not asked.
        return ""
    if weather_asks_air(user_text or ""):
        # Tanda 4c «Whats the air quality hoy?»: the air is answered with its index.
        if isinstance(air, dict) and not _states_weather_number(text, air.get("usAqi")):
            return "missing_state"
        return ""
    if sun_time:
        # Uso real tanda 2 «el horario de la caída del sol para mañana»: the asked
        # day's sun time is the answer (tomorrow's for tomorrow or a later day).
        block = tomorrow if asks_tomorrow else seen.get("today")
        clocks = [block.get(key) for key in ("sunrise", "sunset")] if isinstance(block, dict) else []
        clocks = [clock for clock in clocks if isinstance(clock, str) and clock]
        if clocks and not any(clock in text or clock.lstrip("0") in text for clock in clocks):
            return "missing_state"
        return ""
    if rain_asked or asks_tomorrow:
        # Uso real tanda 2 «¿Me llevo el chubasquero?», «¿Cuántas pulgadas are we
        # getting today?», «dentro de dos días»: rain, rain gear, a rain amount
        # and a later day are answered with the rain probability of the day
        # asked — tomorrow's for tomorrow or later, today's for today, either
        # read when no day is named.
        if asks_tomorrow:
            days = (tomorrow,)
        elif re.search(r"\b(?:hoy|today|tonight|esta\s+(?:noche|tarde|manana))\b", asks):
            days = (seen.get("today"),)
        else:
            days = (seen.get("today"), tomorrow)
        probabilities = [
            day.get("rainProbabilityPercent")
            for day in days
            if isinstance(day, dict) and day.get("rainProbabilityPercent") is not None
        ]
        if probabilities and not any(_states_weather_number(text, value) for value in probabilities):
            return "missing_state"
    for measure, key in (("humidity", "humidityPercent"), ("wind", "windKmh"), ("apparent", "apparentC")):
        if measure in narrow_measures and seen.get(key) is not None and not _states_weather_number(text, seen.get(key)):
            return "missing_state"
    if (
        not any(form in text for form in _weather_number_forms(seen.get("temperatureC")))
        and not rain_asked
        and not asks_tomorrow
        and not narrow_measures
    ):
        return "missing_state"
    return ""


def _news_fact_defect(text: str, payload: dict) -> str:
    """REOPEN1993 grupo N: the reply quotes the observed headlines (at least
    three when the feed gave that many) and names no portal listing instead."""

    if payload.get("operation") != "web.news.headlines":
        return ""
    seen = payload.get("seen")
    if not isinstance(seen, dict) or not isinstance(seen.get("headlines"), list):
        return ""
    titles = [
        str(item.get("title")).strip()
        for item in seen["headlines"]
        if isinstance(item, dict) and isinstance(item.get("title"), str) and item.get("title").strip()
    ]
    if not titles:
        return ""
    folded_text = _reading_fold(text)
    quoted = sum(1 for title in titles if _reading_fold(title) in folded_text)
    if quoted < min(3, len(titles)):
        return "missing_state"
    return ""


def _game_library_fact_defect(text: str, payload: dict) -> str:
    """REOPEN1993 grupo S: the reply names the game and matches the manifest
    state: a started download is not «installed», an already-installed game
    was not downloaded, an uninstall says the game is gone."""

    if payload.get("operation") not in {"game.install.named", "game.uninstall.named"}:
        return ""
    seen = payload.get("seen")
    if not isinstance(seen, dict) or not isinstance(seen.get("state"), str):
        return ""
    folded_text = _reading_fold(text)
    name = seen.get("name")
    if isinstance(name, str) and name.strip() and _reading_fold(name) not in folded_text:
        return "missing_state"
    state = seen["state"]
    if state == "downloading":
        if re.search(r"\b(?:ya\s+(?:esta|quedo)\s+instalad|instalad[oa]\s+(?:correctamente|con exito)|installed successfully|is now installed)\w*", folded_text):
            return "extra_claim"
        if not re.search(r"\b(?:descarg|download|instalando|installing|empez|comenz|started|inici)\w*", folded_text):
            return "missing_state"
    if state == "already_installed" and re.search(r"\b(?:descarg(?:ue|ando|a\b)|download(?:ed|ing)|empez|started)\w*", folded_text) and not re.search(r"\bno\b", folded_text):
        return "extra_claim"
    if state in {"manifest_removed", "manifest_not_installed"} and not re.search(r"\b(?:desinstal|quit|elimin|borr|uninstall|removed|ya no)\w*", folded_text):
        return "missing_state"
    return ""


def _shell_fact_defect(text: str, payload: dict) -> str:
    """REOPEN1993 comandos: a quoted output line must be one the command
    printed; a failed command is not reported as a success; a command with
    output does not get reported as silent."""

    if payload.get("operation") != "shell.command.run":
        return ""
    seen = payload.get("seen")
    if not isinstance(seen, dict) or not isinstance(seen.get("exitCode"), int):
        return ""
    lines = [str(line) for line in seen.get("lines") or [] if isinstance(line, str)]
    stderr = str(seen.get("stderr") or "")
    folded_text = _reading_fold(text)
    printed = _reading_fold("\n".join(lines) + "\n" + stderr)
    for quoted in re.findall(r"[«\"“`]([^»\"”`\n]{4,200})[»\"”`]", text):
        if _reading_fold(quoted) not in printed:
            return "invented_number" if re.search(r"\d", quoted) else "extra_claim"
    failed = seen["exitCode"] != 0
    if failed and re.search(r"\b(?:salio bien|exito|exitosa|exitosamente|correctamente|sin problemas|succeeded|successfully|worked)\b", folded_text) and not re.search(r"\b(?:no|fall|error)\b", folded_text):
        return "extra_claim"
    if not failed and lines and not any(_reading_fold(line) in folded_text for line in lines[:5]):
        return "missing_state"
    if not failed and not lines and not re.search(
        # SHELL2075 H0245 «ejecuta ls» with an empty folder: the instruction says
        # «si no hubo salida, dilo» and «No hubo salida» — the plainest way to say
        # it — was not among the accepted forms, so three faithful drafts died.
        r"\b(?:sin salida|ninguna salida|no hubo salida|no (?:imprimio|produjo|mostro|devolvio|escribio)|"
        r"nada|no output|no lines|nothing|printed nothing|empty|vacia)\b",
        folded_text,
    ):
        return "missing_state"
    return ""


def _package_fact_defect(text: str, payload: dict) -> str:
    """REOPEN1993 grupo G: the reply names the package and does not claim a
    finished install or removal while the process is still running."""

    operation = payload.get("operation")
    seen = payload.get("seen")
    if operation not in {"package.install.commit", "package.uninstall"} or not isinstance(seen, dict):
        return ""
    name = seen.get("name")
    folded_text = _reading_fold(text)
    if isinstance(name, str) and name.strip() and _reading_fold(name) not in folded_text:
        return "missing_state"
    running = seen.get("installing") is True or seen.get("uninstalling") is True
    if running and re.search(
        r"\b(?:instal(?:e|ado|ada)|desinstal(?:e|ado|ada)|quit(?:e|ado|ada)|elimin(?:e|ado|ada)|removed|installed|uninstalled)\b",
        folded_text,
    ) and not re.search(r"\b(?:sigue|todavia|aun|still|empez|comenz|started|running|corriendo|en curso|en marcha)\b", folded_text):
        return "extra_claim"
    return ""


def _wifi_place_fact_defect(text: str, payload: dict) -> str:
    """REOPEN1957 H0170/H0376: when no network is associated with the place
    yet, the reply asks which of the saved networks it is, naming them, and
    never claims a connection. A verified connect by place says so."""

    seen = payload.get("seen")
    reason = payload.get("reason")
    folded_text = _reading_fold(text)
    if isinstance(reason, dict) and reason.get("cause") == _CAUSE_FACT["wifi_place_unknown"]:
        if "?" not in text:
            return "missing_state"
        if re.search(r"(?<!\bno )(?<!\bnot )\b(?:conecte|conectado|conectada|connected|te conecte|listo)\b", folded_text):
            return "reversed_polarity"
        labels = seen.get("savedNetworks") if isinstance(seen, dict) else None
        if isinstance(labels, list) and labels and not any(_reading_fold(str(label)) in folded_text for label in labels):
            return "missing_state"
        return ""
    if payload.get("operation") == "wifi.connect.named" and isinstance(seen, dict) and seen.get("place") and seen.get("connected") is True:
        if not re.search(r"\b(?:conect|connect)", folded_text):
            return "missing_state"
    return ""


def _payload_fact_defect(text: str, payload: dict, user_text: str = "") -> str:
    """El texto público conserva los hechos que el payload le dio.

    Sin esto, «el volumen es el número correspondiente» pasaba con `level` en
    los hechos, y «Tengo lo que necesito para ayudarte» pasaba como respuesta de
    capacidades con `can` delante. Se comprueba contra el payload de este turno,
    no contra una lista de frases esperadas.
    """

    if not isinstance(payload, dict) or not payload:
        return ""
    window_defect = window_fact_defect(text, payload, user_text)
    if window_defect:
        return window_defect
    if _search_report_speaks_as_a_page(text, payload, user_text):
        return "search_report_page_voice"
    if _search_report_shows_the_search(text, payload, user_text):
        # Owner rule 2026-09-24: the lookup is invisible (see _search_report_shows_the_search).
        return "search_report_shows_the_search"
    if _search_report_unsourced_claim(text, payload, user_text):
        # WEB1879 H0060: a sentence of the report summarised causes in its own
        # voice; no result contains them. Reinstated in WEB1889: the turn no
        # longer dies when every candidate falls, so the rule has a way out.
        return "search_report_unsourced_claim"
    if _search_report_runs_long(text, payload, user_text):
        return "search_report_runs_long"
    if (
        _search_results_text(payload) is not None
        and _entity_lookup_query(user_text or "") is None
        and not curiosity_request(user_text or "")
        and re.search(r"https?://", str(text)) is not None
    ):
        # H0463: «DOOM Eternal: idStudio - SteamDB https://steamdb.info/app/…»
        # is a pasted listing, not a report a companion would say; pages are
        # named by title and site. The safety-net report has that shape.
        return "search_report_pasted_urls"
    folded = _reading_fold(text)
    seen = payload.get("seen")
    # A wifi reading observes the WLAN connection, not internet reachability.
    # «The PC is offline» / «no está en línea» were appended to connected=false
    # (NETWORK1161/010-011, 1163/005, 1165/004) while network.status read
    # online=true. Only a reading that carries `online` may speak about it.
    if (
        # The visible payload of a verified success carries only the
        # operation and its observed facts («seen»); failures carry a cause
        # (NETWORK1299: compose-audit payload_keys ['operation', 'seen']).
        isinstance(payload.get("operation"), str)
        and isinstance(seen, dict)
        and seen
        and not payload.get("cause")
        and not payload.get("error")
        and _ACTION_ATTRIBUTED_TO_USER.search(text) is not None
    ):
        # NETWORK1295/1297 «Apagame el bluetooth.» → «Ya apagaste el
        # bluetooth»: the assistant did it, not the person. This is the
        # predicate that gates acceptance (blocked → payload defect), not
        # only the audit label in rejection_reason.
        return "action_attributed_to_user"
    if (
        user_text
        and declined_means(user_text) is not None
        and not payload.get("error")
        and _claims_declined_means(text)
    ):
        # SYSTEM1545 H0076: the person named Python; the reading was direct.
        # A report that says it used or ran a language, a script or a terminal
        # claims a capability the assistant does not have.
        return "claimed_means"
    if (
        payload.get("operation") == "system.status"
        and isinstance(seen, dict)
        and isinstance(seen.get("os"), dict)
        and _invented_windows_version(text, seen["os"])
    ):
        # SYSTEM1305 H0508: «Windows 11 versión 22H2» — no feature-update name
        # or version number is observed beyond major/minor/build.
        return "invented_version"
    if (
        payload.get("operation") == "system.status"
        and isinstance(seen, dict)
        and isinstance(seen.get("memory"), dict)
        and _mislabelled_installed_memory(text, seen["memory"])
    ):
        # SYSTEM1183/1303 H0508: «16,54 GB de RAM instalados» labels the observed
        # total (16,54 GB) as installed when installed_capacity is 17,18 GB.
        return "mislabelled_installed"
    if (
        isinstance(payload.get("operation"), str)
        and payload["operation"].startswith("system.settings.")
        and isinstance(seen, dict)
        and _contradicted_brightness_extreme(text, seen)
    ):
        return _contradicted_brightness_extreme(text, seen)
    if payload.get("operation") in _LEVEL_OPERATIONS and isinstance(seen, dict) and _unobserved_direction(text, seen):
        return "unobserved_direction"
    prior_steps = payload.get("completedStepsInOrder")
    written = _written_file_after_listing(payload)
